$ErrorActionPreference='Stop';$ScriptDir=Split-Path -Parent $MyInvocation.MyCommand.Path;. (Join-Path (Split-Path -Parent $ScriptDir) 'lib/common.ps1')
if(Test-Command node){$v=(& node --version);if(Test-VersionGE $v '20.0.0'){Write-Ok "Node $v ya instalado";& corepack enable 2>$null;& corepack prepare pnpm@9 --activate;exit 0}}
if(-not(Test-Command winget)){throw 'winget no disponible.'};& winget install --id OpenJS.NodeJS.LTS --silent --accept-package-agreements --accept-source-agreements;$machine=[Environment]::GetEnvironmentVariable('PATH','Machine');$user=[Environment]::GetEnvironmentVariable('PATH','User');$env:PATH="$machine;$user";if(-not(Test-Command node)){throw 'node no disponible tras instalación'};& corepack enable;& corepack prepare pnpm@9 --activate;Write-Ok "Node $(& node --version), pnpm $(& pnpm --version)"
